// Command buffers and the list of operations that 2D drawing and 3D scenes are recorded into.

#include "graphics_internal.hpp"

using namespace bb::gfx;

namespace bb::gfx {

	////////////////////////////////////////////////////////////////////////////
	// Commands
	////////////////////////////////////////////////////////////////////////////
	// Between rectangles of the same image, the pixels take a detour through this buffer.
	VkBuffer       scratch        = VK_NULL_HANDLE;
	VkDeviceMemory scratch_memory = VK_NULL_HANDLE;
	VkDeviceSize   scratch_size   = 0;
	bb::buffer<graveyard_entry> graveyard;

	void empty_graveyard()
	{
		for (uint32_t i = 0; i < graveyard.size; i++) {
			vkDestroyBuffer(g.device, graveyard[i].buffer, nullptr);
			vkFreeMemory(g.device, graveyard[i].memory, nullptr);
		}
		graveyard.clear();
	}

	void begin_commands()
	{
		vkResetCommandBuffer(g.cmd, 0);
		VkCommandBufferBeginInfo info = { VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO };
		info.flags                    = VK_COMMAND_BUFFER_USAGE_ONE_TIME_SUBMIT_BIT;
		check(vkBeginCommandBuffer(g.cmd, &info), "vkBeginCommandBuffer");
	}

	int    profile_submits = 0;
	Uint64 profile_wait    = 0;

	void submit_commands(VkSemaphore wait, VkSemaphore signal)
	{
		check(vkEndCommandBuffer(g.cmd), "vkEndCommandBuffer");

		VkPipelineStageFlags stage = VK_PIPELINE_STAGE_TRANSFER_BIT;
		VkSubmitInfo         info  = { VK_STRUCTURE_TYPE_SUBMIT_INFO };
		info.waitSemaphoreCount    = wait ? 1 : 0;
		info.pWaitSemaphores       = &wait;
		info.pWaitDstStageMask     = &stage;
		info.commandBufferCount    = 1;
		info.pCommandBuffers       = &g.cmd;
		info.signalSemaphoreCount  = signal ? 1 : 0;
		info.pSignalSemaphores     = &signal;
		vkResetFences(g.device, 1, &g.fence);
		profile_submits++;
		Uint64 wait_start = SDL_GetPerformanceCounter();
		check(vkQueueSubmit(g.queue, 1, &info, g.fence), "vkQueueSubmit");
		check(vkWaitForFences(g.device, 1, &g.fence, VK_TRUE, UINT64_MAX), "vkWaitForFences");
		profile_wait += SDL_GetPerformanceCounter() - wait_start;
		empty_graveyard();
	}

	void barrier(VkImage img, VkImageLayout from, VkImageLayout to, VkImageAspectFlags aspect)
	{
		VkImageMemoryBarrier2 b            = { VK_STRUCTURE_TYPE_IMAGE_MEMORY_BARRIER_2 };
		b.srcStageMask                     = VK_PIPELINE_STAGE_2_ALL_COMMANDS_BIT;
		b.srcAccessMask                    = VK_ACCESS_2_MEMORY_WRITE_BIT;
		b.dstStageMask                     = VK_PIPELINE_STAGE_2_ALL_COMMANDS_BIT;
		b.dstAccessMask                    = VK_ACCESS_2_MEMORY_READ_BIT | VK_ACCESS_2_MEMORY_WRITE_BIT;
		b.oldLayout                        = from;
		b.newLayout                        = to;
		b.srcQueueFamilyIndex              = VK_QUEUE_FAMILY_IGNORED;
		b.dstQueueFamilyIndex              = VK_QUEUE_FAMILY_IGNORED;
		b.image                            = img;
		b.subresourceRange.aspectMask      = aspect;
		b.subresourceRange.levelCount      = 1;
		b.subresourceRange.layerCount      = 1;

		VkDependencyInfo dep        = { VK_STRUCTURE_TYPE_DEPENDENCY_INFO };
		dep.imageMemoryBarrierCount = 1;
		dep.pImageMemoryBarriers    = &b;
		vkCmdPipelineBarrier2(g.cmd, &dep);
	}

	// Moves the image to the layout, from the one it is in.
	void transition(gpu_image& img, VkImageLayout to)
	{
		if (img.layout != to) {
			barrier(img.image, img.layout, to);
			img.layout = to;
		}
	}

	// Records a run of 2D operations that all draw to the same buffer.
	static void record_2d(uint32_t first, uint32_t end)
	{
		target_ref target = resolve_target(g.ops[first].target);
		if (!target.image) {
			return; // The buffer was freed in the meantime.
		}

		// Everything that is sampled has to be readable, and what is drawn to has to be a color attachment.
		for (uint32_t i = first; i < end; i++) {
			if ((g.ops[i].kind != OP_CLEAR) && g.ops[i].image) {
				image_entry* e = image_of(g.ops[i].image);
				if (e && e->set && (e->image.image != target.image->image)) {
					transition(e->image, VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL);
				}
			}
		}
		transition(*target.image, VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL);

		VkRenderingAttachmentInfo attachment = { VK_STRUCTURE_TYPE_RENDERING_ATTACHMENT_INFO };
		attachment.imageView                 = target.image->view;
		attachment.imageLayout               = VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL;
		attachment.loadOp                    = VK_ATTACHMENT_LOAD_OP_LOAD;
		attachment.storeOp                   = VK_ATTACHMENT_STORE_OP_STORE;

		VkRenderingInfo info      = { VK_STRUCTURE_TYPE_RENDERING_INFO };
		info.renderArea           = { { 0, 0 }, { target.image->width, target.image->height } };
		info.layerCount           = 1;
		info.colorAttachmentCount = 1;
		info.pColorAttachments    = &attachment;
		vkCmdBeginRendering(g.cmd, &info);

		// Drawing is limited to the part of the image that this buffer is.
		VkViewport viewport = { float(target.x), float(target.y), float(target.w), float(target.h), 0, 1 };
		VkRect2D   scissor  = { { target.x, target.y }, { uint32_t(target.w), uint32_t(target.h) } };
		vkCmdSetViewport(g.cmd, 0, 1, &viewport);
		vkCmdSetScissor(g.cmd, 0, 1, &scissor);

		float scale[2] = { 1.0f / float(target.w), 1.0f / float(target.h) };
		vkCmdPushConstants(g.cmd, g.layout, VK_SHADER_STAGE_VERTEX_BIT | VK_SHADER_STAGE_FRAGMENT_BIT, 0, sizeof(scale), scale);
		VkDeviceSize offset = 0;
		vkCmdBindVertexBuffers(g.cmd, 0, 1, &g.vertex_buffer, &offset);

		for (uint32_t i = first; i < end; i++) {
			operation& op = g.ops[i];
			if (op.kind == OP_CLEAR) {
				VkClearAttachment clear = {};
				clear.aspectMask        = VK_IMAGE_ASPECT_COLOR_BIT;
				memcpy(clear.clearValue.color.float32, op.color, sizeof(op.color));
				VkClearRect rect = { scissor, 0, 1 };
				vkCmdClearAttachments(g.cmd, 1, &clear, 1, &rect);
				continue;
			}

			VkDescriptorSet set = g.sets[op.texture];
			if (op.image) {
				image_entry* e = image_of(op.image);
				if (!e || !e->set) {
					continue; // Freed since it was asked to be drawn.
				}
				set = e->set;
			}
			vkCmdBindPipeline(g.cmd, VK_PIPELINE_BIND_POINT_GRAPHICS, op.kind == OP_LINES ? g.lines : g.triangles);
			vkCmdBindDescriptorSets(g.cmd, VK_PIPELINE_BIND_POINT_GRAPHICS, g.layout, 0, 1, &set, 0, nullptr);
			vkCmdPushConstants(g.cmd, g.layout, VK_SHADER_STAGE_VERTEX_BIT | VK_SHADER_STAGE_FRAGMENT_BIT, 16, sizeof(op.mask), op.mask);
			vkCmdDraw(g.cmd, op.count, 1, op.first, 0);
		}
		vkCmdEndRendering(g.cmd);
	}

	// Replays the collected operations into the command buffer, in the order they were asked for.
	void record_operations()
	{
		uint32_t i = 0;
		while (i < g.op_count) {
			operation& op = g.ops[i];
			if (op.kind == OP_SCENE) {
				record_scene(op.first, op.target);
				i++;
			} else if (op.kind == OP_COPY) {
				record_copy(op.first);
				i++;
			} else {
				uint32_t end = i;
				while ((end < g.op_count) && (g.ops[end].kind <= OP_LINES) && (g.ops[end].target == op.target)) {
					end++;
				}
				record_2d(i, end);
				i = end;
			}
		}
		g.op_count     = 0;
		g.vertex_count = 0;
		forget_recorded();
	}

	// Presents the front buffer in the window. Expects an open command buffer, finishes it.
	void present_front(bool copy_back)
	{
		uint32_t index = 0;
		VkResult result = vkAcquireNextImageKHR(g.device, g.swapchain, UINT64_MAX, g.acquired, VK_NULL_HANDLE, &index);
		if (result == VK_ERROR_OUT_OF_DATE_KHR) {
			// Can't present to this swapchain: finish what we recorded, it gets recreated before the next present.
			submit_commands();
			g.resized = true;
			return;
		} else if (result != VK_SUBOPTIMAL_KHR) {
			check(result, "vkAcquireNextImageKHR");
		}

		gpu_image& front = g.buffers[0];
		gpu_image& back  = g.buffers[1];

		if (copy_back) {
			barrier(back.image, VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL, VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL);
			barrier(front.image, VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL, VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL);
			VkImageCopy copy                 = {};
			copy.srcSubresource              = { VK_IMAGE_ASPECT_COLOR_BIT, 0, 0, 1 };
			copy.dstSubresource              = { VK_IMAGE_ASPECT_COLOR_BIT, 0, 0, 1 };
			copy.extent                      = { front.width, front.height, 1 };
			vkCmdCopyImage(g.cmd, back.image, VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL, front.image, VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL, 1, &copy);
			barrier(back.image, VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL, VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL);
			barrier(front.image, VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL, VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL);
		} else {
			barrier(front.image, VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL, VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL);
		}

		barrier(g.swap_images[index], VK_IMAGE_LAYOUT_UNDEFINED, VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL);
		VkImageBlit blit       = {};
		blit.srcSubresource    = { VK_IMAGE_ASPECT_COLOR_BIT, 0, 0, 1 };
		blit.srcOffsets[1]     = { int32_t(front.width), int32_t(front.height), 1 };
		blit.dstSubresource    = { VK_IMAGE_ASPECT_COLOR_BIT, 0, 0, 1 };
		blit.dstOffsets[1]     = { int32_t(g.swap_extent.width), int32_t(g.swap_extent.height), 1 };
		vkCmdBlitImage(g.cmd, front.image, VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL, g.swap_images[index], VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL, 1, &blit, VK_FILTER_NEAREST);
		barrier(g.swap_images[index], VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL, VK_IMAGE_LAYOUT_PRESENT_SRC_KHR);
		barrier(front.image, VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL, VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL);

		submit_commands(g.acquired, g.swap_done[index]);

		VkPresentInfoKHR present   = { VK_STRUCTURE_TYPE_PRESENT_INFO_KHR };
		present.waitSemaphoreCount = 1;
		present.pWaitSemaphores    = &g.swap_done[index];
		present.swapchainCount     = 1;
		present.pSwapchains        = &g.swapchain;
		present.pImageIndices      = &index;
		result                     = vkQueuePresentKHR(g.queue, &present);
		if ((result == VK_ERROR_OUT_OF_DATE_KHR) || (result == VK_SUBOPTIMAL_KHR)) {
			g.resized = true;
		} else {
			check(result, "vkQueuePresentKHR");
		}
	}

	// Records and sends everything that has been asked for.
	void flush()
	{
		if (g.headless || !g.created || (g.op_count == 0)) {
			return;
		}
		begin_commands();
		record_operations();
		if (g.front_touched) {
			g.front_touched = false;
			// Drawing to the front buffer is visible immediately.
			if (g.resized || (g.swapchain == VK_NULL_HANDLE)) {
				submit_commands();
				if (g.resized) {
					destroy_swapchain();
					create_swapchain();
				}
				return;
			}
			present_front(false);
		} else {
			submit_commands();
		}
	}

	////////////////////////////////////////////////////////////////////////////
	// Operations
	////////////////////////////////////////////////////////////////////////////
	operation& add_operation(op_kind kind, int texture, uint32_t vertices, int image, const float* mask)
	{
		static const float no_mask[4] = { 0, 0, 0, 0 };
		if (!mask) {
			mask = no_mask;
		}
		if (g.vertex_count + vertices > max_vertices) {
			flush();
		}
		if (g.target == front_buffer) {
			g.front_touched = true;
		}
		// Merge with the previous operation if possible.
		if (g.op_count > 0) {
			operation& last = g.ops[g.op_count - 1];
			if ((last.kind == kind) && ((kind == OP_TRIANGLES) || (kind == OP_LINES)) && (last.target == g.target) && (last.texture == texture) && (last.image == image) && (memcmp(last.mask, mask, sizeof(last.mask)) == 0)) {
				last.count += vertices;
				g.vertex_count += vertices;
				return last;
			}
		}
		if (g.op_count == g.op_cap) {
			g.op_cap = g.op_cap ? g.op_cap * 2 : 256;
			g.ops    = static_cast<operation*>(realloc(g.ops, g.op_cap * sizeof(operation)));
			if (!g.ops) {
				fail("Out of memory.");
			}
		}
		operation& op = g.ops[g.op_count++];
		op.kind       = kind;
		op.target     = g.target;
		op.texture    = texture;
		op.image      = image;
		memcpy(op.mask, mask, sizeof(op.mask));
		op.first      = g.vertex_count;
		op.count      = vertices;
		g.vertex_count += vertices;
		return op;
	}

	vertex* add_vertices(op_kind kind, int texture, uint32_t count, int image, const float* mask)
	{
		add_operation(kind, texture, count, image, mask);
		return g.vertices + (g.vertex_count - count);
	}

	void set_vertex(vertex& v, float x, float y, float u, float vv)
	{
		v = { x, y, u, vv, g.color[0], g.color[1], g.color[2], 255 };
	}

	void add_rect(float x, float y, float w, float h)
	{
		vertex* v = add_vertices(OP_TRIANGLES, TEXTURE_WHITE, 6);
		set_vertex(v[0], x, y, 0.5f, 0.5f);
		set_vertex(v[1], x + w, y, 0.5f, 0.5f);
		set_vertex(v[2], x, y + h, 0.5f, 0.5f);
		set_vertex(v[3], x + w, y, 0.5f, 0.5f);
		set_vertex(v[4], x + w, y + h, 0.5f, 0.5f);
		set_vertex(v[5], x, y + h, 0.5f, 0.5f);
	}
} // namespace bb::gfx
